package com.bank.dsa;

import java.util.Arrays;
import java.util.logging.*;

public class TwoPointersDemo {
    private static final Logger log = Logger.getLogger(TwoPointersDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PointerTools tools = new PointerTools();

        // Variant 1: opposite-end on SORTED settlement amounts
        int[] sorted = {100, 250, 400, 650, 900};
        int[] pair = tools.findPairSum(sorted, 650); // 250 + 400
        log.info(() -> "Opposite-end pair for target 650: " + Arrays.toString(pair));

        // Variant 2: same-direction compaction (remove cancelled = 0)
        int[] ledger = {500, 0, 300, 0, 0, 900};
        int kept = tools.compactNonZero(ledger);
        log.info(() -> "Compacted ledger kept " + kept + " entries: "
                + Arrays.toString(Arrays.copyOf(ledger, kept)));

        // Variant 3: fast/slow middle of a transaction list
        TxnNode head = TxnNode.of("T1", "T2", "T3", "T4", "T5");
        TxnNode mid = tools.middle(head);
        log.info(() -> "Fast/slow middle transaction: " + mid.id);
    }
}

