class PointerTools {
    private static final Logger log = Logger.getLogger(PointerTools.class.getName());

    // Opposite-end: requires SORTED input. O(n) time, O(1) space.
    int[] findPairSum(int[] a, int target) {
        int left = 0, right = a.length - 1;
        while (left < right) {
            int sum = a[left] + a[right];
            if (sum == target) {
                return new int[]{a[left], a[right]};
            } else if (sum < target) {
                left++;  // need a bigger sum
            } else {
                right--; // need a smaller sum
            }
        }
        log.warning(() -> "No pair summed to " + target);
        return new int[]{-1, -1};
    }

    // Same-direction: slow write pointer, fast read pointer. In-place.
    int compactNonZero(int[] a) {
        int write = 0;
        for (int read = 0; read < a.length; read++) {
            if (a[read] != 0) {
                a[write] = a[read];
                write++;
            }
        }
        return write; // number of kept entries
    }

    // Fast/slow: fast moves 2, slow moves 1. Slow ends at the middle.
    TxnNode middle(TxnNode head) {
        TxnNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }
}

